import {vehicleHistory} from '../services/real-workshop.js';
import {realMode} from '../services/api-service.js';
import {getStore,saveClient,saveVehicle,deleteClient,deleteVehicle,getContext} from '../services/workshop-service.js';
import {e,date,stamp,field,textarea,select,checkbox,placeholder,selectOptions,link,button,submit,form,hint,pageHeader,searchableList,bindForm,go,notify,showModal,table,badge,rowActions,confirmDelete,personCell,phoneFormat,docBadge} from '../components/ui.js';
import {icon} from '../components/icons.js';
import {permissionChecker} from '../services/permissions.js';
const clientLabel=c=>`${c.name} · ${c.documentType} ${c.documentNumber}`;
const vehicleLabel=v=>`${v.plate} · ${v.brand} ${v.model}`;
export function renderClients({root,path,params,session}){
 const s=getStore(),can=permissionChecker(session.role);
 if(path[1]==='nuevo'||path[1]==='editar'){
  if(!can('clientes',path[1]==='editar'?'editar':'crear'))throw new Error('Tu rol no tiene permiso para esta acción.');
  const id=path[1]==='editar'?path[2]:null,c=id?s.clients.find(c=>c.id===id):{};if(!c)throw new Error('No se encontró el cliente.');
  root.innerHTML=pageHeader(id?'Editar cliente':'Nuevo cliente','Complete los datos y seleccione el documento correspondiente.')+form('DATOS DEL CLIENTE',
   field('Nombre completo o razón social','name',c.name||'','text','required maxlength="150" autocomplete="organization"')+
   select('Tipo de documento','documentType',['DNI','RUC',{value:'CE',label:'Carné de extranjería'},'Pasaporte'],c.documentType||'DNI','required')+
   field('Número de documento','documentNumber',c.documentNumber||'','text','required maxlength="20" autocomplete="off"')+
   field('Teléfono','phone',c.phone||'','tel','required maxlength="20" autocomplete="tel"')+
   field('Correo electrónico (opcional)','email',c.email||'','email','maxlength="150" autocomplete="email"')+
   field('Dirección','address',c.address||'','text','required maxlength="250" autocomplete="street-address"'),
   submit(id?'Guardar cambios':'Guardar cliente')+link('Volver a clientes','clientes'));
  const type=root.querySelector('[name="documentType"]');const updateLabel=()=>{const input=root.querySelector('[name="name"]');root.querySelector(`label[for="${input.id}"]`).textContent=type.value==='RUC'?'Razón social':'Nombre completo';const number=root.querySelector('[name="documentNumber"]');number.inputMode=['DNI','RUC'].includes(type.value)?'numeric':'text';};type.onchange=updateLabel;updateLabel();
  bindForm('edit-form',async data=>{const saved=await saveClient(data,id);notify(id?'Cliente actualizado.':'Cliente registrado.');go(params.get('volver')==='recepciones'?`recepciones?cliente=${saved.id}`:'clientes');});return;
 }
 const vehiclesFor=c=>s.vehicles.filter(v=>v.clientId===c.id);
 const overview=`<div class="directory-stats" aria-label="Resumen del directorio"><div>${icon('users')}<strong>${String(s.clients.length).padStart(2,'0')}</strong><span>clientes</span></div><div>${icon('car')}<strong>${String(s.vehicles.length).padStart(2,'0')}</strong><span>vehículos</span></div></div>`;
 searchableList(root,{title:'Clientes',subtitle:'Consulta, registra y administra la información de tus clientes.',actions:overview+(can('clientes','crear')?link(icon('plus')+' Nuevo cliente','clientes/nuevo',true):''),placeholder:'Buscar por cliente, documento o placa…',headers:['Cliente','Tipo','N.º documento','Vehículos','Teléfono','Acciones'],records:s.clients,searchText:c=>`${c.name} ${c.documentType} ${c.documentNumber} ${vehiclesFor(c).map(v=>v.plate).join(' ')}`,row:c=>[personCell(c.name,c.address||c.email),docBadge(c.documentType),`<span class="mono">${e(c.documentNumber)}</span>`,`<div class="vehicle-plates">${vehiclesFor(c).map(v=>`<span class="plate">${e(v.plate)}</span>`).join('')||'<span class="cell-note">Sin vehículos</span>'}</div>`,`<span class="phone-number">${phoneFormat(c.phone)}</span>`,rowActions({editHref:`clientes/editar/${c.id}`,id:c.id,name:c.name,canEdit:can('clientes','editar'),canDelete:can('clientes','eliminar')})],onAction:(action,id)=>{if(action==='delete'){const c=getStore().clients.find(x=>x.id===id);confirmDelete({title:'¿Eliminar cliente?',message:`Vas a eliminar a <strong>${e(c?.name)}</strong> (${e(c?.documentType)} ${e(c?.documentNumber)}).`,onConfirm:async()=>{await deleteClient(id);notify('Cliente eliminado.');go('clientes');}});}}});
 root.insertAdjacentHTML('beforeend',hint('Los contactos para retirar vehículos se registran en Pagos y entrega.'));
}
export function renderVehicles({root,path,params,session}){
 const can=permissionChecker(session.role),s=getStore(),editing=path[1]==='editar',creating=path[1]==='nuevo';
 if(editing||creating){
  if(!can('vehiculos',editing?'editar':'crear'))throw new Error('Tu rol no tiene permiso para esta acción.');
  const id=editing?(path[2]||s.vehicles[0]?.id):null,v=id?s.vehicles.find(v=>v.id===id):{};if(!v)throw new Error('No hay vehículos para actualizar. Registra uno primero.');
  const owner=s.clients.find(c=>c.id===v.clientId);
  let body=editing?select('Seleccionar vehículo registrado (búsqueda por placa)','selectedVehicle',selectOptions(s.vehicles,vehicleLabel),v.id,'required')+field('Placa (se conserva)','plate',v.plate,'text','readonly')+field('Propietario actual (solo lectura)','owner',owner?clientLabel(owner):'','text','readonly'):select('Cliente propietario','clientId',selectOptions(s.clients,clientLabel),params.get('cliente')||'','required')+field('Placa','plate','','text','required maxlength="12" placeholder="ABC-123"');
  body+=select('Marca','brand',['JAC'],v.brand||'JAC','required')+field('Modelo','model',v.model||'','text','required maxlength="60" placeholder="T8, S3, T6…"')+field('Año','year',v.year||new Date().getFullYear(),'number','required min="1950" max="'+(new Date().getFullYear()+1)+'"')+field('Kilometraje actual (km)','mileage',v.mileage||'0.00','text','required inputmode="decimal" placeholder="25300.50"')+textarea('Observaciones (opcional)','notes',v.notes||'','maxlength="1000"');
  if(editing)body+=`<h2 class="form-section-title full-width separated">CAMBIO DE PROPIETARIO · OPCIONAL</h2>`+checkbox('El vehículo cambió de propietario (activar solo cuando corresponda)','transfer')+`<div class="transfer-fields full-width" hidden><div class="form-grid">${select('Nuevo propietario: buscar cliente por nombre o documento','newClientId',selectOptions(s.clients.filter(c=>c.id!==owner.id),clientLabel),'','disabled')}${checkbox('Transferencia verificada por usuario autorizado','transferVerified',false,'disabled')}</div></div>`+hint('La placa y el historial técnico se conservan. Solo se aplica el nuevo propietario si confirmas la transferencia.');
  root.innerHTML=pageHeader(editing?'Actualizar vehículo':'Nuevo vehículo',editing?'Actualiza los datos o registra una transferencia verificada.':'Asocia una placa única con un cliente existente.')+form(editing?'DATOS DEL VEHÍCULO':'DATOS DEL VEHÍCULO · PRIMER REGISTRO',body,submit(editing?'Guardar cambios':'Guardar vehículo')+link('Volver a vehículos','vehiculos'));
  if(editing){root.querySelector('[name="selectedVehicle"]').onchange=ev=>go('vehiculos/editar/'+ev.target.value);root.querySelector('[name="transfer"]').onchange=ev=>{const area=root.querySelector('.transfer-fields');area.hidden=!ev.target.checked;area.querySelectorAll('input,select').forEach(el=>el.disabled=!ev.target.checked);};}
  bindForm('edit-form',async data=>{const saved=await saveVehicle(data,id,session.id);notify(editing?'Vehículo actualizado; historial conservado.':'Vehículo registrado.');go(params.get('volver')==='recepciones'?`recepciones?cliente=${saved.clientId}&vehiculo=${saved.id}`:'vehiculos');});return;
 }
 searchableList(root,{title:'Vehículos',subtitle:'Consulta vehículos y actualiza sus datos desde una sola opción.',actions:(can('vehiculos','crear')?link(icon('plus')+' Nuevo vehículo','vehiculos/nuevo',true):'')+(can('vehiculos','editar')?link('Actualizar vehículo','vehiculos/editar'):''),placeholder:'Buscar por placa, modelo o cliente…',headers:['Placa','Marca','Modelo','Año','Propietario actual','Acciones'],records:s.vehicles,searchText:v=>`${v.plate} ${v.model} ${s.clients.find(c=>c.id===v.clientId)?.name}`,row:v=>[`<span class="plate">${e(v.plate)}</span>`,e(v.brand),e(v.model),e(v.year),personCell(s.clients.find(c=>c.id===v.clientId)?.name||'—'),rowActions({editHref:`vehiculos/editar/${v.id}`,id:v.id,name:v.plate,canEdit:can('vehiculos','editar'),canDelete:can('vehiculos','eliminar'),extra:`<button type="button" class="row-icon row-history" data-action="history" data-id="${e(v.id)}" title="Ver historial" aria-label="Ver historial de ${e(v.plate)}">${icon('history')}</button>`})],onAction:(action,id)=>{if(action==='history')showVehicleHistory(id).catch(error=>notify(error.message));if(action==='delete'){const v=getStore().vehicles.find(x=>x.id===id);confirmDelete({title:'¿Eliminar vehículo?',message:`Vas a eliminar el vehículo con placa <strong>${e(v?.plate)}</strong> (${e(v?.brand)} ${e(v?.model)}).`,onConfirm:async()=>{await deleteVehicle(id);notify('Vehículo eliminado.');go('vehiculos');}});}}});
}
async function showVehicleHistory(id){
 if(realMode){const h=(await vehicleHistory(id)).data,s=getStore(),v=s.vehicles.find(v=>v.id===id),owner=id=>s.clients.find(c=>c.id===id)?.name||`Cliente #${id}`;const rows=h.receptions.map(r=>[date(r.createdAt),e(r.id),e(owner(r.clientId)),e(r.findings||'Pendiente de diagnóstico'),e(r.quotes.map(q=>q.code||q.orderId||'Sin orden').join(', ')),e(r.quotes.map(q=>q.state||'').join(', '))]);const transfers=h.transfers.map((t,i)=>[stamp(t.from),e(i?owner(h.transfers[i-1].clientId):'Registro inicial'),e(owner(t.clientId)),e(t.actorId||'—')]);showModal(`Historial · ${v.plate}`,`<h2 class="form-section-title">ATENCIONES Y DIAGNÓSTICOS</h2>${table(['Fecha','Recepción','Cliente de la atención','Diagnóstico','Orden','Estado'],rows)}<h2 class="form-section-title separated">CAMBIOS DE PROPIETARIO</h2>${table(['Fecha y hora','Propietario anterior','Nuevo propietario','Verificado por'],transfers)}`);return;}
 const s=getStore(),v=s.vehicles.find(v=>v.id===id);const receptions=s.receptions.filter(r=>r.vehicleId===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
 const rows=receptions.map(r=>{const d=s.diagnoses.find(d=>d.receptionId===r.id),q=s.quotes.find(q=>q.diagnosisId===d?.id),o=s.orders.find(o=>o.quoteId===q?.id);return [date(r.createdAt),e(r.id),e(s.clients.find(c=>c.id===r.clientId)?.name),e(d?.findings||'Pendiente de diagnóstico'),o?`<a class="text-link" href="#/ordenes/editar/${e(o.id)}" data-history-link>${e(o.id)}</a>`:'—',o?badge(o.delivery?'Entregado':o.state):'—'];});
 const transfers=(v.transfers||[]).map(t=>[stamp(t.at),e(s.clients.find(c=>c.id===t.previousClientId)?.name),e(s.clients.find(c=>c.id===t.newClientId)?.name),e(s.users.find(u=>u.id===t.by)?.name)]);
 const dialog=showModal(`Historial · ${v.plate}`,`<p class="dialog-intro">${e(v.brand)} ${e(v.model)} · ${e(v.mileage)} km</p><h2 class="form-section-title">ATENCIONES Y DIAGNÓSTICOS</h2>${table(['Fecha','Recepción','Cliente de la atención','Diagnóstico','Orden','Estado'],rows)}<h2 class="form-section-title separated">CAMBIOS DE PROPIETARIO</h2>${table(['Fecha y hora','Propietario anterior','Nuevo propietario','Verificado por'],transfers,'No se registraron transferencias.')}`);
 dialog.querySelectorAll('[data-history-link]').forEach(a=>a.addEventListener('click',()=>dialog.close()));
}
